//! Generate frontend command names from the actual native protocol; no database is opened.
use std::io::{self, Write};
use wealthfolio_business::investment_journal::InvestmentJournalCommand;
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut out = io::BufWriter::new(io::stdout().lock());
    writeln!(out,"// Generated by cargo run -p wealthfolio-business --example investment_journal_types --offline.")?;
    writeln!(
        out,
        "// Update this file from the native protocol; do not edit the command list by hand."
    )?;
    writeln!(out, "export const INVESTMENT_JOURNAL_COMMANDS = [")?;
    for command in InvestmentJournalCommand::ALL {
        writeln!(out, "  {},", serde_json::to_string(command.name())?)?;
    }
    writeln!(out,"] as const;\n\nexport type InvestmentJournalCommand = (typeof INVESTMENT_JOURNAL_COMMANDS)[number];")?;
    Ok(())
}
